1	-- Fix #9: divisão inteira truncava avg_dwell_ms pra baixo (viés sistemático).
2	-- Fix #8: top-20 sem tiebreak podia descartar página recém-vista.
3	-- Fix M1: RLS admin do gidape_events usava profiles.id/role (não existem) —
4	--         correto é profiles.user_id e role_id (via mia_get_user_role).
5	
6	-- ── Trigger com média em numeric ──────────────────────────────
7	CREATE OR REPLACE FUNCTION fn_update_behavioral_profile()
8	RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER AS $$
9	DECLARE
10	    v_hour int4;
11	    v_peak jsonb;
12	    v_feat jsonb;
13	    v_feat_id text;
14	    v_feat_count int4;
15	    v_pages jsonb;
16	    v_page_found bool := false;
17	    v_dwell_ms int8;
18	    v_page text;
19	    v_from text;
20	    v_to text;
21	BEGIN
22	    v_hour := EXTRACT(HOUR FROM NEW.created_at)::int4;
23	    v_page := NEW.page;
24	
25	    INSERT INTO mia_user_patterns(user_id) VALUES(NEW.user_id) ON CONFLICT (user_id) DO NOTHING;
26	
27	    SELECT COALESCE(peak_hours, '{}') INTO v_peak FROM mia_user_patterns WHERE user_id = NEW.user_id;
28	    v_peak := jsonb_set(v_peak, ARRAY[v_hour::text], to_jsonb(COALESCE((v_peak ->> v_hour::text)::int4, 0) + 1));
29	
30	    IF NEW.event_type = 'feature_use' THEN
31	        v_feat_id := NEW.properties->>'feature_id';
32	        IF v_feat_id IS NOT NULL THEN
33	            SELECT COALESCE(feature_usage_map, '{}') INTO v_feat FROM mia_user_patterns WHERE user_id = NEW.user_id;
34	            v_feat_count := COALESCE((v_feat ->> v_feat_id)::int4, 0) + 1;
35	            v_feat := jsonb_set(v_feat, ARRAY[v_feat_id], to_jsonb(v_feat_count));
36	            UPDATE mia_user_patterns SET feature_usage_map = v_feat, peak_hours = v_peak, behavioral_updated_at = now()
37	                WHERE user_id = NEW.user_id;
38	            RETURN NEW;
39	        END IF;
40	    END IF;
41	
42	    IF NEW.event_type = 'page_exit' THEN
43	        v_dwell_ms := (NEW.properties->>'dwell_ms')::int8;
44	        v_from := v_page;
45	        v_to := NEW.properties->>'next_page';
46	
47	        IF v_dwell_ms IS NOT NULL AND v_dwell_ms > 0 THEN
48	            DECLARE
49	                v_dwell_map jsonb;
50	                v_old_avg numeric;
51	                v_old_count int4;
52	                v_new_avg int8;
53	            BEGIN
54	                SELECT COALESCE(avg_dwell_ms, '{}') INTO v_dwell_map FROM mia_user_patterns WHERE user_id = NEW.user_id;
55	                v_old_avg := COALESCE((v_dwell_map -> v_page ->> 'avg')::numeric, 0);
56	                v_old_count := COALESCE((v_dwell_map -> v_page ->> 'count')::int4, 0);
57	                -- média em numeric, arredondada (sem truncamento sistemático)
58	                v_new_avg := round(((v_old_avg * v_old_count) + v_dwell_ms) / (v_old_count + 1))::int8;
59	                v_dwell_map := jsonb_set(v_dwell_map, ARRAY[v_page],
60	                    jsonb_build_object('avg', v_new_avg, 'count', v_old_count + 1));
61	                UPDATE mia_user_patterns SET avg_dwell_ms = v_dwell_map, peak_hours = v_peak, behavioral_updated_at = now()
62	                    WHERE user_id = NEW.user_id;
63	            END;
64	        END IF;
65	
66	        IF v_from IS NOT NULL AND v_to IS NOT NULL AND v_from != v_to THEN
67	            INSERT INTO user_nav_graph(user_id, from_page, to_page, weight, last_seen_at)
68	                VALUES(NEW.user_id, v_from, v_to, 1, now())
69	                ON CONFLICT (user_id, from_page, to_page)
70	                DO UPDATE SET weight = user_nav_graph.weight + 1, last_seen_at = now();
71	        END IF;
72	        RETURN NEW;
73	    END IF;
74	
75	    IF NEW.event_type = 'mia_suggestion_acted' THEN
76	        UPDATE mia_user_patterns
77	            SET mia_suggestion_act_rate = (
78	                COALESCE(mia_suggestion_act_rate, 0) * 0.8 +
79	                CASE WHEN (NEW.properties->>'acted')::bool THEN 0.2 ELSE 0 END
80	            ), peak_hours = v_peak, behavioral_updated_at = now()
81	            WHERE user_id = NEW.user_id;
82	        RETURN NEW;
83	    END IF;
84	
85	    IF NEW.event_type = 'page_enter' THEN
86	        SELECT COALESCE(top_pages, '[]'::jsonb) INTO v_pages FROM mia_user_patterns WHERE user_id = NEW.user_id;
87	        v_page_found := EXISTS(SELECT 1 FROM jsonb_array_elements(v_pages) elem WHERE elem->>'page' = v_page);
88	
89	        IF v_page_found THEN
90	            v_pages := COALESCE((
91	                SELECT jsonb_agg(
92	                    CASE WHEN elem->>'page' = v_page
93	                        THEN jsonb_set(elem, '{count}', to_jsonb((elem->>'count')::int4 + 1))
94	                        ELSE elem END
95	                ) FROM jsonb_array_elements(v_pages) elem
96	            ), '[]'::jsonb);
97	        ELSE
98	            v_pages := v_pages || jsonb_build_object('page', v_page, 'count', 1);
99	        END IF;
100	
101	        -- top-20 por count, com a página atual SEMPRE preservada (tiebreak),
102	        -- pra uma página recém-vista não ser podada no mesmo insert que a criou.
103	        v_pages := COALESCE((
104	            SELECT jsonb_agg(elem ORDER BY (elem->>'count')::int4 DESC)
105	            FROM (
106	                SELECT elem FROM jsonb_array_elements(v_pages) elem
107	                ORDER BY (CASE WHEN elem->>'page' = v_page THEN 1 ELSE 0 END) DESC,
108	                         (elem->>'count')::int4 DESC
109	                LIMIT 20
110	            ) sub
111	        ), v_pages);
112	
113	        UPDATE mia_user_patterns SET top_pages = COALESCE(v_pages, '[]'::jsonb), peak_hours = v_peak, behavioral_updated_at = now()
114	            WHERE user_id = NEW.user_id;
115	        RETURN NEW;
116	    END IF;
117	
118	    UPDATE mia_user_patterns SET peak_hours = v_peak, behavioral_updated_at = now() WHERE user_id = NEW.user_id;
119	    RETURN NEW;
120	END;
121	$$;
122	
123	-- ── Fix M1: RLS admin do gidape_events ────────────────────────
124	DROP POLICY IF EXISTS "gidape_events_select_admin" ON gidape_events;
125	CREATE POLICY "gidape_events_select_admin" ON gidape_events FOR SELECT
126	    USING (
127	        -- subselect garante avaliação única (não por linha) — best-practice RLS
128	        (SELECT lower(coalesce(mia_get_user_role(auth.uid()), ''))) IN ('admin','master','administrator','administrador')
129	    );
130	
131	-- ── Realtime na config (pro flip da flag valer sem reload) ─────
132	do $$
133	begin
134	  if not exists (
135	    select 1 from pg_publication_tables
136	    where pubname='supabase_realtime' and schemaname='public' and tablename='mia_runtime_config'
137	  ) then
138	    alter publication supabase_realtime add table mia_runtime_config;
139	  end if;
140	end $$;
